  const sm   = vals.map((_,i)=>median(vals.slice(Math.max(0,i-SMOOTH),   Math.min(n,i+SMOOTH+1))));
  const base = vals.map((_,i)=>median(vals.slice(Math.max(0,i-BASE_WIN), Math.min(n,i+BASE_WIN+1))));
  const dev  = vals.map((_,i)=> base[i]>0 ? (sm[i]-base[i])/base[i] : 0);
  const cand = []; for (let i=0;i<n;i++) if (Math.abs(dev[i])*100 >= FLOOR_PCT) cand.push(i);
  cand.sort((a,b)=>Math.abs(dev[b])-Math.abs(dev[a]));
  const picked=[]; for (const i of cand){ if (picked.every(j=>Math.abs(i-j)>MERGE_WEEKS)) picked.push(i);
                                          if (picked.length>=TOP_N) break; }
  const shoulder = (FLOOR_PCT*SHOULDER_FRAC)/100;
  return picked.map(i => { const sg=Math.sign(dev[i]); let l=i,r=i;
    while (l-1>=0        && Math.sign(dev[l-1])===sg && Math.abs(dev[l-1])>=shoulder) l--;
