  arr.forEach((p,k) => { const h = override ? override[k] : p.hits;
    for (let i=0;i<p.n;i++) { if (p.flags[i]) { ti++; if(!h[i]) mi++; }
                             else            { to++; if(!h[i]) mo++; } } });
  return { ti, to, mi, mo, R: (mi/ti)/(mo/to) };
